{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2173-09-12 00:35:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee, one of the surgical team members. You're here because of increasing pain around your G-tube site?"
    },
    {
      "turn_number": 2,
      "time": "2173-09-12 00:37:00",
      "speaker": "Patient",
      "text": "Yes, it's been sharp and constant since this morning. I ran out of my oxycodone, and Tylenol isn’t helping much."
    },
    {
      "turn_number": 3,
      "time": "2173-09-12 00:40:00",
      "speaker": "Doctor",
      "text": "I see you've had this pain before and were admitted a few times. The last CT showed inflammation, but no infection or abscess. We’ll keep you overnight for pain control."
    },
    {
      "turn_number": 4,
      "time": "2173-09-12 00:42:00",
      "speaker": "Patient",
      "text": "That sounds familiar. Is it the same issue again?"
    },
    {
      "turn_number": 5,
      "time": "2173-09-12 00:45:00",
      "speaker": "Doctor",
      "text": "Likely yes. Your exam today shows no redness or swelling around the tube, and your vitals are stable. We’ll start you on oxycodone to see how you respond."
    },
    {
      "turn_number": 6,
      "time": "2173-09-12 00:48:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. I’m just worried it won’t help like last time."
    },
    {
      "turn_number": 7,
      "time": "2173-09-12 00:50:00",
      "speaker": "Doctor",
      "text": "We’ll monitor closely. If oral meds aren’t enough, we can use IV Dilaudid for breakthrough pain. For now, you’ll stay on continuous tube feeds—NutriHep at 50 cc/hr."
    },
    {
      "turn_number": 8,
      "time": "2173-09-12 00:53:00",
      "speaker": "Patient",
      "text": "I’ve been on that at home. No issues with the feeds themselves."
    },
    {
      "turn_number": 9,
      "time": "2173-09-12 00:55:00",
      "speaker": "Doctor",
      "text": "Good. We’re not seeing signs of infection—no fever or lab abnormalities. We’ll continue watching your pain and response to medication."
    },
    {
      "turn_number": 10,
      "time": "2173-09-12 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How’s the pain now after the oxycodone?"
    },
    {
      "turn_number": 11,
      "time": "2173-09-12 08:17:00",
      "speaker": "Patient",
      "text": "Much better. I’d say it’s down from a 7 to about a 3. I’m glad the medicine’s working."
    },
    {
      "turn_number": 12,
      "time": "2173-09-12 08:20:00",
      "speaker": "Doctor",
      "text": "That’s great to hear. We’ll keep you on the same plan for now. You’re still on continuous tube feeds, and we’ll continue monitoring your intake and output."
    },
    {
      "turn_number": 13,
      "time": "2173-09-12 08:23:00",
      "speaker": "Patient",
      "text": "Should I keep checking my blood sugar like at home?"
    },
    {
      "turn_number": 14,
      "time": "2173-09-12 08:25:00",
      "speaker": "Doctor",
      "text": "Yes, definitely. Given your history of hypoglycemia after gastric bypass, it’s important to monitor regularly. We’ll remind you before discharge."
    },
    {
      "turn_number": 15,
      "time": "2173-09-12 12:05:00",
      "speaker": "Doctor",
      "text": "We just completed an enteral infusion to ensure your feeds are running smoothly. You’re doing well—no nausea or discomfort."
    },
    {
      "turn_number": 16,
      "time": "2173-09-12 12:08:00",
      "speaker": "Patient",
      "text": "I didn’t even notice. It feels normal, which is a relief."
    },
    {
      "turn_number": 17,
      "time": "2173-09-12 16:00:00",
      "speaker": "Doctor",
      "text": "You’ve done well overnight. Pain is controlled, you’re afebrile, and labs are stable. We’re planning to discharge you soon."
    },
    {
      "turn_number": 18,
      "time": "2173-09-12 16:03:00",
      "speaker": "Patient",
      "text": "That’s good. What should I do at home?"
    },
    {
      "turn_number": 19,
      "time": "2173-09-12 16:06:00",
      "speaker": "Doctor",
      "text": "Resume your regular tube feeds at 50 cc/hr, continue monitoring blood sugar, and take oxycodone 10 mg every 4 hours as needed for pain."
    },
    {
      "turn_number": 20,
      "time": "2173-09-12 16:09:00",
      "speaker": "Patient",
      "text": "And if the pain doesn’t get better?"
    },
    {
      "turn_number": 21,
      "time": "2173-09-12 16:12:00",
      "speaker": "Doctor",
      "text": "Call your surgeon or return to the ED if pain worsens, doesn’t improve in a few hours, or if you develop fever, chills, or other new symptoms."
    },
    {
      "turn_number": 22,
      "time": "2173-09-12 16:15:00",
      "speaker": "Patient",
      "text": "Got it. I’ll follow up with my surgeon and take it easy at home."
    },
    {
      "turn_number": 23,
      "time": "2173-09-12 16:18:00",
      "speaker": "Doctor",
      "text": "Also, avoid driving or alcohol while on oxycodone. Keep taking your other regular medications like fluoxetine, atenolol, and rifaximin."
    },
    {
      "turn_number": 24,
      "time": "2173-09-12 16:21:00",
      "speaker": "Patient",
      "text": "I remember from last time. I’ll be careful."
    },
    {
      "turn_number": 25,
      "time": "2173-09-12 16:24:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. A nurse will give you written instructions and your prescription for oxycodone."
    },
    {
      "turn_number": 26,
      "time": "2173-09-12 16:27:00",
      "speaker": "Patient",
      "text": "Thank you. I appreciate the help getting the pain under control."
    },
    {
      "turn_number": 27,
      "time": "2173-09-12 16:30:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and don’t hesitate to reach out if anything changes."
    },
    {
      "turn_number": 28,
      "time": "2173-09-12 17:15:00",
      "speaker": "Patient",
      "text": "I will. Have a good day."
    }
  ],
  "summary": {
    "admission_start": "2173-09-12 00:35:00",
    "admission_end": "2173-09-12 17:15:00",
    "summary_paragraph": "The patient was admitted for sharp pain at her G-tube site, which had worsened after running out of oxycodone. She had a history of similar episodes with prior admissions showing inflammatory changes without infection. On admission, she was started on oxycodone with good pain control and remained on continuous tube feeds (NutriHep at 50 cc/hr). She was afebrile and hemodynamically stable throughout. IV Dilaudid was available for breakthrough pain but not required after initial oral dosing. An enteral infusion was completed without issues. She was discharged home with a prescription for oxycodone, instructions to resume home feeds and monitor blood glucose, and advised to follow up with her surgeon.",
    "problems": [
      "Abdominal pain, other specified site",
      "Other and unspecified postsurgical nonabsorption",
      "Gastrostomy status",
      "Personal history of Methicillin resistant Staphylococcus aureus",
      "Bariatric surgery status",
      "Other chronic nonalcoholic liver disease",
      "Polycystic ovaries",
      "Personal history of peptic ulcer disease"
    ]
  }
}
